-- name: by_schema
-- dialect: teradata
LOCKING ROW FOR ACCESS
SELECT TRIM(i.DatabaseName) AS schema_name, TRIM(i.TableName) AS table_name, COALESCE(NULLIF(TRIM(i.IndexName), ''), CASE WHEN TRIM(i.IndexType) = 'K' THEN 'PK_' || TRIM(i.TableName) WHEN TRIM(i.IndexType) IN ('P', 'Q') THEN 'PI_' || TRIM(i.TableName) || '_' || CAST(i.IndexNumber AS VARCHAR(12)) ELSE 'IDX_' || TRIM(i.TableName) || '_' || CAST(i.IndexNumber AS VARCHAR(12)) END) AS index_name, TRIM(i.ColumnName) AS column_name, i.ColumnPosition AS column_position, TRIM(i.IndexType) AS index_type, CASE WHEN TRIM(i.UniqueFlag) = 'Y' THEN 1 ELSE 0 END AS is_unique, CASE WHEN TRIM(i.IndexType) IN ('K', 'P', 'Q') THEN 1 ELSE 0 END AS is_primary, CASE WHEN NULLIF(TRIM(i.IndexName), '') IS NULL THEN 1 ELSE 0 END AS catalog_name_generated FROM DBC.IndicesV i JOIN DBC.TablesV t ON UPPER(TRIM(i.DatabaseName)) = UPPER(TRIM(t.DatabaseName)) AND UPPER(TRIM(i.TableName)) = UPPER(TRIM(t.TableName)) WHERE UPPER(TRIM(i.DatabaseName)) = UPPER(TRIM(COALESCE(:schema_name, DATABASE))) AND UPPER(TRIM(i.DatabaseName)) NOT IN ('DBC', 'SYSUDTLIB', 'SYSLIB', 'TD_SYSFNLIB', 'SYSSPATIAL', 'SYSBAR', 'LOCKLOGSHREDDER', 'SQLJ', 'TDSTATS', 'TD_SERVER_DB', 'CRASHDUMPS') AND TRIM(t.TableKind) IN ('T', 'O') AND TRIM(i.IndexType) IN ('P', 'Q', 'S', 'K', 'U', 'N', 'V', 'H', 'O')  ORDER BY TRIM(i.DatabaseName), TRIM(i.TableName), i.IndexNumber, i.ColumnPosition;

-- name: by_table
-- dialect: teradata
LOCKING ROW FOR ACCESS
SELECT TRIM(i.DatabaseName) AS schema_name, TRIM(i.TableName) AS table_name, COALESCE(NULLIF(TRIM(i.IndexName), ''), CASE WHEN TRIM(i.IndexType) = 'K' THEN 'PK_' || TRIM(i.TableName) WHEN TRIM(i.IndexType) IN ('P', 'Q') THEN 'PI_' || TRIM(i.TableName) || '_' || CAST(i.IndexNumber AS VARCHAR(12)) ELSE 'IDX_' || TRIM(i.TableName) || '_' || CAST(i.IndexNumber AS VARCHAR(12)) END) AS index_name, TRIM(i.ColumnName) AS column_name, i.ColumnPosition AS column_position, TRIM(i.IndexType) AS index_type, CASE WHEN TRIM(i.UniqueFlag) = 'Y' THEN 1 ELSE 0 END AS is_unique, CASE WHEN TRIM(i.IndexType) IN ('K', 'P', 'Q') THEN 1 ELSE 0 END AS is_primary, CASE WHEN NULLIF(TRIM(i.IndexName), '') IS NULL THEN 1 ELSE 0 END AS catalog_name_generated FROM DBC.IndicesV i JOIN DBC.TablesV t ON UPPER(TRIM(i.DatabaseName)) = UPPER(TRIM(t.DatabaseName)) AND UPPER(TRIM(i.TableName)) = UPPER(TRIM(t.TableName)) WHERE UPPER(TRIM(i.DatabaseName)) = UPPER(TRIM(COALESCE(:schema_name, DATABASE))) AND UPPER(TRIM(i.DatabaseName)) NOT IN ('DBC', 'SYSUDTLIB', 'SYSLIB', 'TD_SYSFNLIB', 'SYSSPATIAL', 'SYSBAR', 'LOCKLOGSHREDDER', 'SQLJ', 'TDSTATS', 'TD_SERVER_DB', 'CRASHDUMPS') AND TRIM(t.TableKind) IN ('T', 'O') AND TRIM(i.IndexType) IN ('P', 'Q', 'S', 'K', 'U', 'N', 'V', 'H', 'O')  AND UPPER(TRIM(i.TableName)) = UPPER(TRIM(:table_name)) ORDER BY TRIM(i.DatabaseName), TRIM(i.TableName), i.IndexNumber, i.ColumnPosition;
